export type CampaignStatus = "active" | "paused" | "exhausted";

export interface CampaignState {
  campaignId: string;
  status: CampaignStatus;
  bidCpmMicros: number;
  dailyBudgetMicros: number;
  version: number;
}

export interface CampaignChangedEvent {
  type: "campaign.changed";
  state: CampaignState;
}

export interface CampaignSource {
  loadAll(): Promise<CampaignState[]>;
}

import type { CampaignChangedEvent, CampaignSource, CampaignState } from "./types";

export interface Metrics {
  increment(name: string, tags?: Record<string, string>): void;
  gauge(name: string, value: number): void;
}

export class CampaignStateCache {
  private readonly entries = new Map<string, CampaignState>();
  private loadedAt = 0;

  constructor(
    private readonly source: CampaignSource,
    private readonly metrics: Metrics,
    private readonly now: () => number = Date.now,
  ) {}

  async warm(): Promise<void> {
    const all = await this.source.loadAll();
    for (const state of all) {
      this.apply(state, "snapshot");
    }
    this.loadedAt = this.now();
    this.metrics.gauge("campaign_cache.size", this.entries.size);
  }

  onEvent(evt: CampaignChangedEvent): void {
    this.apply(evt.state, "event");
  }

  private apply(incoming: CampaignState, origin: "snapshot" | "event"): void {
    const existing = this.entries.get(incoming.campaignId);
    if (existing && existing.version === incoming.version) {
      this.metrics.increment("campaign_cache.skipped", { origin });
      return;
    }
    this.entries.set(incoming.campaignId, incoming);
    this.metrics.increment("campaign_cache.applied", { origin });
  }

  isServable(campaignId: string): CampaignState | null {
    const state = this.entries.get(campaignId);
    if (!state || state.status !== "active") {
      return null;
    }
    return state;
  }

  snapshotAgeMs(): number {
    return this.loadedAt === 0 ? Infinity : this.now() - this.loadedAt;
  }
}

import type { CampaignStateCache } from "./campaignCache";

export interface BidRequest {
  requestId: string;
  candidateCampaignIds: string[];
  floorCpmMicros: number;
}

export interface Bid {
  requestId: string;
  campaignId: string;
  cpmMicros: number;
}

const MAX_SNAPSHOT_AGE_MS = 10 * 60 * 1000;

export class Bidder {
  constructor(private readonly cache: CampaignStateCache) {}

  bid(req: BidRequest): Bid | null {
    if (this.cache.snapshotAgeMs() > MAX_SNAPSHOT_AGE_MS) {
      return null;
    }
    let best: Bid | null = null;
    for (const id of req.candidateCampaignIds) {
      const state = this.cache.isServable(id);
      if (!state || state.bidCpmMicros < req.floorCpmMicros) {
        continue;
      }
      if (!best || state.bidCpmMicros > best.cpmMicros) {
        best = { requestId: req.requestId, campaignId: id, cpmMicros: state.bidCpmMicros };
      }
    }
    return best;
  }
}
